"""Phase 3: writes items.sql (and items_undo.sql) creating the Bloodangel items in OpenMU.
Each item is cloned from a Season 6 item of the same kind (ItemDefinition, classes, options, base power-ups,
requirements) and then given the Season 19 values: power-ups scaled by new/old, requirements replaced.
Input: the Phase 3 item list (S19 ItemList rows) and the client item files of the reference items."""
import json, os, re, sys

ITEMS = sys.argv[1]
OUT = os.path.dirname(os.path.abspath(__file__))
CLIENT = os.path.join(OUT, '../../versions/shared/items')
INDEX_OVERRIDE = {(2, 22): 30}
# Reference item (group, number) per new item kind.
WEAPON_REF = {(0, 42): (0, 20), (0, 44): (0, 28), (0, 46): (0, 35), (0, 89): (0, 31), (2, 22): (2, 18), (4, 28): (4, 24),
              (5, 41): (5, 33), (5, 43): (5, 34), (5, 57): (5, 23), (6, 34): (6, 19), (6, 44): (6, 17), (6, 70): (6, 21)}
ARMOR_REF = {'DarkKnight': 29, 'DarkWizard': 30, 'FairyElf': 31, 'MagicGladiator': 32, 'DarkLord': 33, 'Summoner': 44, 'RageFighter': 59}
THIRD = {'DarkWizard': 3, 'DarkKnight': 7, 'FairyElf': 11, 'MagicGladiator': 13, 'DarkLord': 17, 'Summoner': 23, 'RageFighter': 25}
# Power-up designation -> (S19 attribute, client field of the reference item).
POWER = {
    'Minimum Physical Base Damage By Weapon': ('MinDamage', 'DmgMin'), 'Maximum Physical Base Damage By Weapon': ('MaxDamage', 'DmgMax'),
    'Minimum Curse Base Damage': ('MinDamage', 'DmgMin'), 'Maximum Curse Base Damage': ('MaxDamage', 'DmgMax'),
    'Base Defense': ('Defense', 'Def'), 'Defense Rate (PvM)': ('SuccessfulBlocking', 'DefRate'),
    'Staff Rise Percentage': ('MagicPower', 'MagicPwr'), 'Scepter Rise Percentage': ('MagicPower', 'MagicPwr'), 'Book Rise Percentage': ('MagicPower', 'MagicPwr'),
}
REQ = {'Total Strength Requirement Value': 'ReqStrength', 'Total Agility Requirement Value': 'ReqAgility', 'Total Energy Requirement Value': 'ReqEnergy',
       'Total Vitality Requirement Value': 'ReqVitality', 'Total Leadership': 'ReqCommand', 'Level': 'ReqLevel'}

def client_item(g, n):
    for d, _, fs in os.walk(CLIENT):
        for f in fs:
            if f.endswith('.ts') and not f.endswith('.test.ts'):
                t = open(os.path.join(d, f)).read()
                if re.search(rf'^  Group: {g},$', t, re.M) and re.search(rf'^  Index: {n},$', t, re.M):
                    return {k: int(v) for k, v in re.findall(r"^  '?([\w/]+)'?: (-?\d+),$", t, re.M)}
    raise SystemExit(f'no client item {g}/{n}')

def uid(g, n): return f"'00000080-{g:04x}-{n:04x}-0000-000000000000'"
q = lambda s: "'" + s.replace("'", "''") + "'"
items = json.load(open(ITEMS))
do, undo = ['-- Phase 3: Bloodangel items (generated by gen_items.py)', 'BEGIN;'], ['BEGIN;']
for it in items:
    g = it['cat']; n0 = int(it['Index']); n = INDEX_OVERRIDE.get((g, n0), n0)
    classes = [c for c in THIRD if it.get(c, '0') != '0']
    rg, rn = WEAPON_REF.get((g, n0)) or (g, ARMOR_REF[classes[0]])
    ref = client_item(rg, rn); new = uid(g, n)
    R = f'(select "Id" from config."ItemDefinition" where "Group"={rg} and "Number"={rn})'
    do.append(f'-- {g}/{n} {it["Name"]} from {rg}/{rn}')
    do.append(f'''insert into config."ItemDefinition" ("Id","ItemSlotId","ConsumeEffectId","SkillId","GameConfigurationId","Number","Width","Height","DropsFromMonsters","IsAmmunition","IsBoundToCharacter","Name","DropLevel","MaximumItemLevel","Durability","Group","Value","MaximumSockets","PetExperienceFormula","StorageLimitPerCharacter","MaximumDropLevel","IsQuestItem","IsDroppable","IsPersonalStoreSellable","IsRepairable","IsSellableToNpc","IsStorable","IsTradable","IntroducedIn","IsActive","PriceDefinitionId","ExcellentBonus","ExcellentRaisesLevel","StatProfileId")
  select {new},"ItemSlotId","ConsumeEffectId","SkillId","GameConfigurationId",{n},{int(it['Width'])},{int(it['Height'])},false,"IsAmmunition","IsBoundToCharacter",{q(it['Name'])},{int(it['DropLevel'])},"MaximumItemLevel",{int(it['Durability'] or 0) or 'i."Durability"'},{g},"Value","MaximumSockets","PetExperienceFormula","StorageLimitPerCharacter","MaximumDropLevel","IsQuestItem","IsDroppable","IsPersonalStoreSellable","IsRepairable","IsSellableToNpc","IsStorable","IsTradable","IntroducedIn","IsActive","PriceDefinitionId","ExcellentBonus","ExcellentRaisesLevel","StatProfileId"
  from config."ItemDefinition" i where i."Id"={R};''')
    do.append(f'insert into config."ItemDefinitionCharacterClass" select {new}, "Id" from config."CharacterClass" where "Number" in ({",".join(str(THIRD[c]) for c in classes)});')
    do.append(f'insert into config."ItemDefinitionItemOptionDefinition" select {new}, "ItemOptionDefinitionId" from config."ItemDefinitionItemOptionDefinition" where "ItemDefinitionId"={R};')
    do.append(f'insert into config."ItemBasePowerUpDefinition" ("Id","TargetAttributeId","BonusPerLevelTableId","ItemDefinitionId","BaseValue","AggregateType") select gen_random_uuid(),"TargetAttributeId","BonusPerLevelTableId",{new},"BaseValue","AggregateType" from config."ItemBasePowerUpDefinition" where "ItemDefinitionId"={R};')
    for des, (src, field) in POWER.items():
        old, val = ref.get(field, 0), int(it.get(src, '0') or 0)
        if old > 0 and val > 0:
            do.append(f'update config."ItemBasePowerUpDefinition" p set "BaseValue" = round(p."BaseValue" * {val}::numeric / {old}) from config."AttributeDefinition" a where p."ItemDefinitionId"={new} and a."Id"=p."TargetAttributeId" and a."Designation"={q(des)};')
    if int(it.get('AttackSpeed', '0') or 0):
        do.append(f'update config."ItemBasePowerUpDefinition" p set "BaseValue" = {int(it["AttackSpeed"])} from config."AttributeDefinition" a where p."ItemDefinitionId"={new} and a."Id"=p."TargetAttributeId" and a."Designation"=\'Attack Speed by Weapons\';')
    for des, src in REQ.items():
        val = int(it.get(src, '0') or 0)
        if val > 0:
            do.append(f'insert into config."AttributeRequirement" ("Id","AttributeId","ItemDefinitionId","MinimumValue") select gen_random_uuid(), "Id", {new}, {val} from config."AttributeDefinition" where "Designation"={q(des)};')
    undo.append(f'delete from config."ItemDefinitionCharacterClass" where "ItemDefinitionId"={new}; delete from config."ItemDefinitionItemOptionDefinition" where "ItemDefinitionId"={new}; delete from config."ItemBasePowerUpDefinition" where "ItemDefinitionId"={new}; delete from config."AttributeRequirement" where "ItemDefinitionId"={new}; delete from config."ItemDefinition" where "Id"={new};')
do.append(f'select count(*) || \' Bloodangel items\' from config."ItemDefinition" where "Id"::text like \'00000080-%\' and "Name" ilike \'%blood%angel%\';')
do.append('COMMIT;'); undo.append('COMMIT;')
open(os.path.join(OUT, 'items.sql'), 'w').write('\n'.join(do) + '\n')
open(os.path.join(OUT, 'items_undo.sql'), 'w').write('\n'.join(undo) + '\n')
print(len(items), 'items')
